def solve(haystack, needle):
    if len(needle) > len(haystack):
        return -1

    base = 257
    mod = 10**9 + 7

    def get_hash(s):
        hash_val = 0
        for c in s:
            hash_val = (hash_val * base + ord(c)) % mod
        return hash_val

    def get_prefix_hash(s):
        prefix = [0] * (len(s) + 1)
        for i in range(len(s)):
            prefix[i+1] = (prefix[i] * base + ord(s[i])) % mod
        return prefix

    n = len(needle)
    h = len(haystack)

    prefix = get_prefix_hash(haystack)
    needle_hash = get_hash(needle)

    base_pow = pow(base, n, mod)

    for i in range(h - n + 1):
        current_hash = (prefix[i + n] - prefix[i] * base_pow) % mod
        if current_hash == needle_hash:
            return i
    return -1

