def solve(nums, target):
    def helper1(arr, x):
        left, right = 0, len(arr) - 1
        while left <= right:
            mid = (left + right) // 2
            if arr[mid] == x:
                return mid
            elif arr[mid] < x:
                left = mid + 1
            else:
                right = mid - 1
        return -1

    nums_sorted = sorted(nums)
    nums_with_indices = sorted((num, i) for i, num in enumerate(nums))

    for i in range(len(nums_with_indices)):
        num_i, idx_i = nums_with_indices[i]
        complement = target - num_i
        j = helper1(nums_sorted, complement)
        if j != -1 and j != i:
            return [idx_i, nums_with_indices[j][1]]

