    def helper1(pattern):
        m = len(pattern)
        fail = [0] * m
        j = 0
        for i in range(1, m):
            while j > 0 and pattern[i] != pattern[j]:
                j = fail[j - 1]
            if pattern[i] == pattern[j]:
                j += 1
                fail[i] = j
        return fail

    if len(needle) > len(haystack):
        return -1

    fail = helper1(needle)
    j = 0
    for i in range(len(haystack)):
        while j > 0 and haystack[i] != needle[j]:
            j = fail[j - 1]
        if haystack[i] == needle[j]:
            j += 1
            if j == len(needle):
                return i - j + 1
    return -1

