    groups = {}
    for p in points:
        root = find(p)
        if root not in groups:
            groups[root] = [p]
        else:
            groups[root].append(p)

    # Create merged intervals
    merged = []
    for group in groups.values():
        merged.append([group[0], group[-1]])

    merged.sort()
    return merged

