        if len(arr) <= 1:
            return arr[0]
        pivot = arr[len(arr) // 2]
        left = [x for x in arr if x < pivot]
        middle = [x for x in arr if x == pivot]
        right = [x for x in arr if x > pivot]
        left_len = len(left)
        if k <= left_len:
            return quickselect(left, k)
        elif k <= left_len + len(middle):
            return pivot
        else:
            return quickselect(right, k - left_len - len(middle))
    return quickselect(nums, k)

