        hash_val = 0
        for c in s:
            hash_val = (hash_val * base + ord(c)) % mod
        return hash_val

    def get_prefix_hash(s):
        prefix = [0] * (len(s) + 1)
        for i in range(len(s)):
            prefix[i+1] = (prefix[i] * base + ord(s[i])) % mod
        return prefix

