def solve(intervals):
    if not intervals:
        return []

    # Create a mapping from interval endpoints and intermediate points
    unique_points = sorted(set(p for interval in intervals for p in interval))
    point_to_index = {
        p: i for i, p in enumerate(unique_points)
    }

    # Union-Find structure
    class UnionFind:
        def __init__(self, size):
            self.parent = list(range(size))
            self.size = [1] * size

        def find(self, x):
            if self.parent[x] != x:
                self.parent[x] = self.find(self.parent[x])
            return self.parent[x]

        def union(self, x, y):
            x_root = self.find(x)
            y_root = self.find(y)
            if x_root == y_root:
                return
            if self.size[x_root] < self.size[y_root]:
                x_root, y_root = y_root, x_root
            self.parent[y_root] = x_root
            self.size[x_root] += self.size[y_root]

    uf = UnionFind(len(unique_points))

    # Union all points within each interval
    for start, end in intervals:
        s = point_to_index[start]
        e = point_to_index[end]
        for i in range(s, e):
