from collections import Counter

def solve(nums, k):
    freq = Counter(nums)
    max_freq = max(freq.values())
    groups = [[] for _ in range(max_freq + 1)]
    for num, count in freq.items():
        groups[count] = [num] + groups[count]

    result = []
    for i in range(max_freq, 0, -1):
        result.extend(groups[i])
        if len result >= k:
            break

    return result[:k]

