def solve(nums, k):
    def kth_smallest(nums, k):
        nums = nums[:]
        for i in range(len(nums) - 1, 0, -1):
            j = 2 * i
            if j < len(nums) and nums[j] < nums[j - 1]:
                j -= 1
            if nums[i] < nums[j]:
                nums[i], nums[j] = nums[j], nums[i]
            i -= 1
        return nums[k - 1]

    return kth_smallest(nums, k)

