import random
from collections import Counter

def solve(nums, k):
    counts = Counter(nums)
    keys = list(counts.keys())
    values = list(counts.values())

   def partition(arr, left,右, pivot_idx):
        pivot = arr[pivot_idx]
        arr[pivot_idx], arr[右] = arr[右], arr[pivot_idx]
        store_idx = left
        for i in range(left, 右):
            if arr[i] < pivot:
                arr[store_idx], arr[i] = arr[i], arr[store_idx]
                store_idx += 1
        arr[右], arr[store_idx] = arr[store_idx], arr[右]
        return store_idx

   def quickselect(arr, left, 右, k):
        while left <= 右:
            pivot_idx = random.randint(left, 右)
            pivot_idx = partition(arr, left, 右, pivot_idx)
            if pivot_idx == k:
                return arr[pivot_idx]
            elif pivot_idx < k:
                left = pivot_idx + 1
            else:
                右 = pivot_idx - 1
