        return -1

    def compute_lps(pattern):
        lps = [0] * len(pattern)
        length = 0
        for i in range(1, len(pattern)):
            while length > 0 andpattern[i] != pattern[length]:
                length = lps[length - 1]
            if pattern[i] == pattern[length]:
                length += 1
                lps[i] = length
            else:
                lps[i] = 0
        return lps

    lps = compute_lps(needle)
    i = j = 0
    while i < len(haystack):
        if haystack[i] == needle[j]:
            i += 1
            j += 1
            if j == len(needle):
                    return i - j
        else:
            if j != 0:
                j = lps[j - 1]
            else:
                i += 1
    return -1

