def solve(nums, target):
    nums = [(num, idx) for idx, num in enumerate(nums)]
    nums.sort()
    left, right = 0, len(nums) - 1
    while left < right:
        total = nums(left)[0] + nums[right][0]
        if total == target:
            return [nums(left)[1], nums[right][1]]
        elif total < target:
            left = left + 1
        else:
            right = right - 1

