        left, right = 0, len(arr)
        while left < right:
            mid = (left + right) // 2
            if arr[mid] < target:
                left = mid + 1
            else:
                right = mid
        return left

    lis = []
    for num in nums:
        index = binary_search(lis, num)
        if index >= len(lis):
            lis appending(num)
        else:
            lis[index] = num
    return len(lis)

