    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * n
    components = 0

    for node in range(n):
        if not visited[node]:
            components += 1
            # Use recursion for DFS instead of BFS
            def dfs(node):
                visited[node] = True
                for neighbor in graph[node]:
                    if not visited[neighbor]:
                        dfs(neighbor)
            dfs(node)

    return components

