def solve(n, edges):
    visited = [False] * n
    count = 0

    def dfs(node):
        stack = [node]
        while stack:
            current = stack.pop()
            if visited[current]:
                continue
            visited[current] = True
            for neighbor in range(n):
                if not visited[neighbor] and any(edge == (current, neighbor) or edge == (neighbor, current) for edge in edges):
                    stack.append(neighbor)

    for i in range(n):
        if not visited[i]:
            dfs(i)
            count += 1

    return count

